namespace ghidra.framework.main.projectdata.actions;




using docking.action;
using docking.action;
using ghidra.framework.main;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatable;
using ghidra.framework.model;

public class ProjectDataOpenDefaultToolAction : FrontendProjectTreeAction {

	public ProjectDataOpenDefaultToolAction(string owner, string group) : base("Open File", owner)
    {
		setPopupMenuData(new MenuData(new string[] { "Open in Default Tool" }, group));
		setKeyBindingData(new KeyBindingData(KeyEvent.VK_ENTER, 0));
		markHelpUnnecessary();
	}

	/* @Override */
	protected void actionPerformed(ProjectDataContext context) {
		List<DomainFile> selectedFiles = context.getSelectedFiles();
		// NOTE: Seems like we should confirm opening more than one file
		AppInfo.getActiveProject().getToolServices().launchDefaultTool(selectedFiles);
	}

	/* @Override */
	protected bool isEnabledForContext(ProjectDataContext context) {
		if (!context.getSelectedFolders().isEmpty()) {
			return false;
		}
		List<DomainFile> selectedFiles = context.getSelectedFiles();
		if (selectedFiles.isEmpty()) {
			return false;
		}
		foreach (DomainFile file in context.getSelectedFiles()) {
			if (file.isLink() && file.getLinkInfo().isFolderLink()) {
				return false;
			}
		}
		return true;
	}
}
